import json


def diff(a, b):
    ops = []
    _diff(a, b, "$", ops)
    return sorted(ops)


def _equal(a, b):
    return type(a) is type(b) and a == b


def _render(value):
    return json.dumps(value, sort_keys=True)


def _diff(a, b, path, ops):
    if _equal(a, b):
        return
    if isinstance(a, dict) and isinstance(b, dict):
        for key in a:
            if key not in b:
                ops.append(f"- {path}.{key}: {_render(a[key])}")
            else:
                _diff(a[key], b[key], f"{path}.{key}", ops)
        for key in b:
            if key not in a:
                ops.append(f"+ {path}.{key}: {_render(b[key])}")
        return
    if isinstance(a, list) and isinstance(b, list):
        common = min(len(a), len(b))
        for i in range(common):
            _diff(a[i], b[i], f"{path}[{i}]", ops)
        for i in range(common, len(a)):
            ops.append(f"- {path}[{i}]: {_render(a[i])}")
        for i in range(common, len(b)):
            ops.append(f"+ {path}[{i}]: {_render(b[i])}")
        return
    ops.append(f"~ {path}: {_render(a)} -> {_render(b)}")
```

